199	                enc_key: spin::Mutex::new(None),
200	                endpoint: spin::Mutex::new(None),
201	                keys: spin::Mutex::new(KeyWheel {
202	                    next: None,
203	                    current: None,
204	                    previous: None,
205	                    retired: vec![],
206	                }),
207	                staged_packets: spin::Mutex::new(ArrayDeque::new()),
208	            }),
